import{_ as t,H as p,f as i,i as a}from"./chunks/framework.BH2BK_3i.js";const u=JSON.parse('{"title":"热点速递 | 《羊了个羊》原来根本没想让我过关！","description":"","frontmatter":{},"headers":[{"level":2,"title":"为什么这么简单这么火？","slug":"为什么这么简单这么火","link":"#为什么这么简单这么火","children":[]},{"level":2,"title":"从业者可以从中得到什么启发？","slug":"从业者可以从中得到什么启发","link":"#从业者可以从中得到什么启发","children":[]},{"level":2,"title":"《羊了个羊》后面会变成什么样？","slug":"《羊了个羊》后面会变成什么样","link":"#《羊了个羊》后面会变成什么样","children":[]},{"level":2,"title":"延伸阅读","slug":"延伸阅读","link":"#延伸阅读","children":[]}],"relativePath":"商业思维案例笔记/热点速递｜《羊了个羊》原来根本没想让我过关！.md","filePath":"商业思维案例笔记/热点速递｜《羊了个羊》原来根本没想让我过关！.md","lastUpdated":1795554691000}'),E={name:"商业思维案例笔记/热点速递｜《羊了个羊》原来根本没想让我过关！.md"};function n(s,e,l,o,r,B){return p(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="热点速递-《羊了个羊》原来根本没想让我过关" tabindex="-1">热点速递 | 《羊了个羊》原来根本没想让我过关！ <a class="header-anchor" href="#热点速递-《羊了个羊》原来根本没想让我过关" aria-label="Permalink to &quot;热点速递 | 《羊了个羊》原来根本没想让我过关！&quot;">​</a></h1><p>你好，我是雄峰。</p><p>最近一款叫做“羊了个羊”的微信小游戏火爆全网，到底是有多火呢？</p><p>不管是微博、抖音还是朋友圈，都有《羊了个羊》的身影。9 月 14 日，微博热搜榜甚至出现了 8 条《羊了个羊》相关词条，抖音上也有大量吐槽这款小游戏“难玩”“容易上头”的高赞视频。</p><p>不少游戏主播从过往的“永劫”“金铲铲”转播《羊了个羊》，朋友圈里只要有人通过了第二关，就会引来大量的评论、羡慕以及求教。这究竟是一个什么样的游戏？</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%95%86%E4%B8%9A%E6%80%9D%E7%BB%B4%E6%A1%88%E4%BE%8B%E7%AC%94%E8%AE%B0/images/%25E7%2583%25AD%25E7%2582%25B9%25E9%2580%259F%25E9%2580%2592/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%95%86%E4%B8%9A%E6%80%9D%E7%BB%B4%E6%A1%88%E4%BE%8B%E7%AC%94%E8%AE%B0/images/%25E7%2583%25AD%25E7%2582%25B9%25E9%2580%259F%25E9%2580%2592/1.png" alt=""></a></p><ul><li>图片来源于网络</li></ul><p>其实很简单，《羊了个羊》是一个“三消玩法”+Roguelike（生成随机、进程单向）的微信小游戏，附带魔性的背景音乐，酷似“小羊肖恩”的动画形象，还有过关之后独特的地域排名。</p><p>你是不是想问，为什么这么简单的一款游戏也可以火爆全网？</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%95%86%E4%B8%9A%E6%80%9D%E7%BB%B4%E6%A1%88%E4%BE%8B%E7%AC%94%E8%AE%B0/images/%25E7%2583%25AD%25E7%2582%25B9%25E9%2580%259F%25E9%2580%2592/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%95%86%E4%B8%9A%E6%80%9D%E7%BB%B4%E6%A1%88%E4%BE%8B%E7%AC%94%E8%AE%B0/images/%25E7%2583%25AD%25E7%2582%25B9%25E9%2580%259F%25E9%2580%2592/2.png" alt=""></a></p><ul><li>图片来源于网络</li></ul><h2 id="为什么这么简单这么火" tabindex="-1">为什么这么简单这么火？ <a class="header-anchor" href="#为什么这么简单这么火" aria-label="Permalink to &quot;为什么这么简单这么火？&quot;">​</a></h2><p>先说一个点，即使游戏按照《羊了个羊》重新抄一遍，也不见得可以这么火，任何的现象级游戏都有一定的偶然性，我们分析的只能是其确定性的那一部分。</p><p>首先，《羊了个羊》易上手、难过关，刚一上手就是极大的心理反差，从而激发玩家反复玩的心理。</p><p>《羊了个羊》本质上是一款消消乐游戏，这种玩法用户受众极广。国内日活最高的游戏并不是王者荣耀，而是《开心消消乐》。</p><p>而这款游戏的不同之处在于，《开心消消乐》是循序渐进的关卡策略，一关一关地变难，但是《羊了个羊》第二关就很难通过，这就形成了一个极大的心理落差，会让玩家显得措手不及。</p><p>不少玩家戏言：第一关是 1+1，第二关是考研。就是这样，大量玩家还是想试一试：为什么过不了第二关？于是，出于好奇和不服输的想法，玩家又会持续去玩。</p><p>游戏难玩的地方就在于其附带的 Roguelike 元素。物品出现的情况非常随机，在消除到最后仅剩几个物品的时候，一些物品只剩下 1 件或者 2 件，根本不可能通关。可以说，游戏设计之初，就有一定玩家无法过关的概率。这种设计也是违背游戏设计直觉的策略。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%95%86%E4%B8%9A%E6%80%9D%E7%BB%B4%E6%A1%88%E4%BE%8B%E7%AC%94%E8%AE%B0/images/%25E7%2583%25AD%25E7%2582%25B9%25E9%2580%259F%25E9%2580%2592/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%95%86%E4%B8%9A%E6%80%9D%E7%BB%B4%E6%A1%88%E4%BE%8B%E7%AC%94%E8%AE%B0/images/%25E7%2583%25AD%25E7%2582%25B9%25E9%2580%259F%25E9%2580%2592/3.png" alt=""></a></p><ul><li>图片来源于网络</li></ul><p>此前，一款类似的游戏《变态马里奥》同样火爆全网。起初跟正常的“马里奥”游戏一模一样，但实际上大量的玩法和 NPC 都做了修改，boss 可以隐身，技能还覆盖全屏。这就导致很多人在第一屏就挂掉。</p><p>和《羊了个羊》一致，这类熟悉的玩法 /IP，叠加高难度的玩法反差，引发了较大的用户话题。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%95%86%E4%B8%9A%E6%80%9D%E7%BB%B4%E6%A1%88%E4%BE%8B%E7%AC%94%E8%AE%B0/images/%25E7%2583%25AD%25E7%2582%25B9%25E9%2580%259F%25E9%2580%2592/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%95%86%E4%B8%9A%E6%80%9D%E7%BB%B4%E6%A1%88%E4%BE%8B%E7%AC%94%E8%AE%B0/images/%25E7%2583%25AD%25E7%2582%25B9%25E9%2580%259F%25E9%2580%2592/4.png" alt=""></a></p><ul><li>图片来源于网络</li></ul><p>其次，《羊了个羊》有一个非常有特色的“地域排名”。当地域元素植入游戏，瞬间激发了大量玩家的热情。</p><p>玩家每次通关，就能为自己所在的地区添加一只“羊”，各个省份和城市按照“羊”的总数由高到低排序，每个地区都被称为一支“羊队”。大量用户会自发地为自己的省份增加一只羊而拼命地玩，于是爆肝一下午或者一整天。</p><p>想想“广东人吃福建人”“江苏是散装”的梗，地域永远是互联网的流量密码之一。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%95%86%E4%B8%9A%E6%80%9D%E7%BB%B4%E6%A1%88%E4%BE%8B%E7%AC%94%E8%AE%B0/images/%25E7%2583%25AD%25E7%2582%25B9%25E9%2580%259F%25E9%2580%2592/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%95%86%E4%B8%9A%E6%80%9D%E7%BB%B4%E6%A1%88%E4%BE%8B%E7%AC%94%E8%AE%B0/images/%25E7%2583%25AD%25E7%2582%25B9%25E9%2580%259F%25E9%2580%2592/5.png" alt=""></a></p><ul><li>图片来源于网络</li></ul><p>最后，《羊了个羊》病毒化传播的成功。</p><p>微信小游戏一个非常有意思的点就是社会化的分享和传播。简单来说，就是当用户玩游戏的过程中碰到一些较难的关卡，可以通过分享给好友以及群聊的方式，来获取特殊道具和重玩的机会。</p><p>这种方式非常有助于游戏的病毒式传播，有不少用户就是反馈朋友微信发给我，然后在微博上或者抖音上刷到，进入就出不来了。观察行业上的数据即可知，《羊了个羊》95% 的新增源自搜索与分享，基本上无广告投放。</p><p>但是，这种方式可遇不可求，核心还是《羊了个羊》极具话题性的特质，变态的难关引发了全网热议。</p><p>当然，并不是具备了上述特点的小游戏都可以成功。相反，这种情况很看天意，毕竟那么多游戏都有这个因素，但是火起来的只有《羊了个羊》。</p><h2 id="从业者可以从中得到什么启发" tabindex="-1">从业者可以从中得到什么启发？ <a class="header-anchor" href="#从业者可以从中得到什么启发" aria-label="Permalink to &quot;从业者可以从中得到什么启发？&quot;">​</a></h2><p>《羊了个羊》火爆全网，其实给游戏以及上下游的从业者带来了不同程度的启发。</p><p>对小游戏领域的开发者来说（比如豪腾嘉科，小游戏的头部开发者），这是一个以小博大的机会点。</p><p>据坊间传闻，这个小游戏因为接入了微信激励视频的广告变现机制，在 9 月 14 日那一天就获得 400 多万以上的广告收入，如果持续火爆整个 9 月份起码可以产生 1 亿以上的收入，而相应的开发成本非常低。有点类似于14 年 Flappy Bird 火爆全球的情况。</p><p>那么，是否可以参考上述的玩法和核心机制，更换不同的题材、不同的 IP 呢？比如“变态消消乐”，比如“喵了个咪”等等，套用一样的玩法，但是用不同的题材和 IP 疯狂复制。</p><p>对广告平台来说（比如 Ohayoo 或者微信优先），这是一个小游戏发行方向的变化。</p><p>有人计算过，正常一局使用 3 个道具，一局需要看 1 分半的广告。这就意味着，玩 50 局要看75 分钟广告；玩 100 局，要看 2 个半小时广告；玩 500 局，要看 12 个半小时广告。而“看广告”的机制设定，会促使广告平台的广告库存大幅增加，假设广告平台要分给《羊了个羊》1 千万的收入，那么平台本身可以赚取的收入则更多。</p><p>所以，各大广告平台都有针对小游戏孵化的策略，比如字节 Ohayoo 成立的核心目的，就是打造小游戏领域的增长飞轮，过往“飞”的方式是一边提升变现的效率，一边优化买量的成本，实现小游戏的低买和高卖，让小游戏的收入飞起来。</p><p>但是《羊了个羊》的新增没有任何广告费用，而是将病毒化传播和裂变做到了极致，从而火爆全网，通过裂变增长飞轮取代了原有传统的买量增长飞轮。</p><p>最后，对游戏平台产品来说（比如华为游戏中心），这是一个非常好的扩大用户规模的机会点。</p><p>据坊间流传出来的数据来看，《羊了个羊》三天的 DAU 分别如下。</p><ul><li>9 月 12 日：500 万；9 月 13 日：800 万；9 月 14 日：2000 万 +。</li></ul><p>反过来想，什么样的产品可以如此迅速地拉高一个产品的活跃量呢？只有全网爆火的现象级游戏可以带动。</p><p>由于《羊了个羊》没有版号，所以当前只在微信和抖音上以小游戏的方式上架使用，传统的各大游戏中心基本不支持小游戏的游玩，错失了这一部分的流量增长。</p><p>那么，假如各大垂类游戏社区也支持小游戏的上架和使用呢？则会大幅拉高平台的用户规模。也许，后续各大游戏中心都会尝试支持小游戏，从而把握住对应的流量增长所带来的收益。</p><h2 id="《羊了个羊》后面会变成什么样" tabindex="-1">《羊了个羊》后面会变成什么样？ <a class="header-anchor" href="#《羊了个羊》后面会变成什么样" aria-label="Permalink to &quot;《羊了个羊》后面会变成什么样？&quot;">​</a></h2><p>按照结构性表达的方式，我们还需要在分析完核心内容之后，进一步完成信息的延伸和判断。</p><p>目前《羊了个羊》只有第二关，但 DAU 在这类游戏中是非常好的，相关的热度在短期内还可以持续一、两周左右。而且，市面上出现了《羊了个羊》的外挂，可以一站式通过第二关。那么，站在游戏开发者自身的角度，下一步会怎么做呢？</p><p>这个问题也是同行所关心的。</p><p>是做产品矩阵，基于《羊了个羊》持续推出类似的新产品？比如推出同玩法的喵了个咪（猫咪题材），或者联动一些老牌 IP，做出一个新版小游戏？</p><p>还是持续推出新的关卡？比如从第二关，延展到第三关、第四关去？</p><p>或者在原有的基础上做新的分发玩法？比如当前虽然是一个三消类的游戏，那么是否可以在上面增加跑酷相关的玩法？做一个“羊了个羊”版的 BT 神庙逃亡？</p><p>不论是什么动作，核心目的都是延续游戏的生命周期以及商业价值。从传统游戏的角度来看，它不是一个好玩的游戏，不管是画风、玩法还是通过率，都没有令人称道的地方，但是其作为一个纯商业小游戏而言，无疑是极其成功的存在。</p><p>好了，本期的热点速递到这里就结束了。如果你对《羊了个羊》有更多想要分享的看法，以及更多希望了解的热点信息，也欢迎你在留言区和我互动。我们建立了一个读者交流群，欢迎你的加入！如果你觉得有所收获，也可以把这节课分享给你的朋友一起学习。</p><p>我们下一讲见。</p><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><p>和《羊了个羊》类似，通过广告变现的爆款产品《Flappy Bird》《阳光养猪场》它们如何变现？爆火的背后有什么相同点吗？</p><p>《04｜收益（上）：阳光养猪场等网赚游戏为什么在 19 年后突然火了？》</p><p>广告主、广告平台、用户之间的关系是什么样的？</p><p>《03｜效率：为什么 Facebook 的客户以中小为主？》</p><p>什么是结构性表达：在分析一个问题或现象时，思路应该是怎么样的？</p><p>《12 ｜练习课（下）：如何用结构性思考去理解 20 多年中国互联网发展的变化？》</p>',66)])])}const g=t(E,[["render",n]]);export{u as __pageData,g as default};
